macro_rules! deps {
    () => {
        Clone!();
        Id!();
        Note!();
        Rewrite!();
    };
}

macro_rules! Change {
    () => {
        deps!();
        # [doc = " Represents any possible change in order to turn one tree into another."] # [derive (Debug , Clone , Copy)] pub enum Change < 'a , 'old , 'new > { # [doc = " An entry was added, like the addition of a file or directory."] Addition { # [doc = " The location of the file or directory, if [tracking](crate::diff::Options::track_path) was enabled."] # [doc = ""] # [doc = " It may be empty if neither [file names](crate::diff::Options::track_filename()) nor [file paths](crate::diff::Options::track_path())"] # [doc = " are tracked."] location : & 'a BStr , # [doc = " The mode of the added entry."] entry_mode : gix_object :: tree :: EntryMode , # [doc = " Identifies a relationship between this instance and another one,"] # [doc = " making it easy to reconstruct the top-level of directory changes."] relation : Option < tree :: visit :: Relation > , # [doc = " The object id of the added entry."] id : Id < 'new > , } , # [doc = " An entry was deleted, like the deletion of a file or directory."] Deletion { # [doc = " The location of the file or directory, if [tracking](crate::diff::Options::track_path) was enabled."] # [doc = ""] # [doc = " Otherwise, this value is always an empty path."] location : & 'a BStr , # [doc = " The mode of the deleted entry."] entry_mode : gix_object :: tree :: EntryMode , # [doc = " Identifies a relationship between this instance and another one,"] # [doc = " making it easy to reconstruct the top-level of directory changes."] relation : Option < tree :: visit :: Relation > , # [doc = " The object id of the deleted entry."] id : Id < 'old > , } , # [doc = " An entry was modified, e.g. changing the contents of a file adjusts its object id and turning"] # [doc = " a file into a symbolic link adjusts its mode."] Modification { # [doc = " The location of the file or directory, if [tracking](crate::diff::Options::track_path) was enabled."] # [doc = ""] # [doc = " It may be empty if neither [file names](crate::diff::Options::track_filename()) nor [file paths](crate::diff::Options::track_path())"] # [doc = " are tracked."] location : & 'a BStr , # [doc = " The mode of the entry before the modification."] previous_entry_mode : gix_object :: tree :: EntryMode , # [doc = " The object id of the entry before the modification."] previous_id : Id < 'old > , # [doc = " The mode of the entry after the modification."] entry_mode : gix_object :: tree :: EntryMode , # [doc = " The object id after the modification."] id : Id < 'new > , } , # [doc = " Entries are considered rewritten if they are not trees and they, according to some understanding of identity, were renamed"] # [doc = " or copied."] # [doc = " In case of renames, this means they originally appeared as [`Deletion`](Change::Deletion) signalling their source as well as an"] # [doc = " [`Addition`](Change::Addition) acting as destination."] # [doc = ""] # [doc = " In case of copies, the `copy` flag is true and typically represents a perfect copy of a source was made."] # [doc = ""] # [doc = " This variant can only be encountered if [rewrite tracking](crate::diff::Options::track_rewrites()) is enabled."] # [doc = ""] # [doc = " Note that mode changes may have occurred as well, i.e. changes from executable to non-executable or vice-versa."] Rewrite { # [doc = " The location of the source of the rename operation."] # [doc = ""] # [doc = " It may be empty if neither [file names](crate::diff::Options::track_filename()) nor [file paths](crate::diff::Options::track_path())"] # [doc = " are tracked."] source_location : & 'a BStr , # [doc = " Identifies a relationship between the source and another source,"] # [doc = " making it easy to reconstruct the top-level of directory changes."] source_relation : Option < tree :: visit :: Relation > , # [doc = " The mode of the entry before the rename."] source_entry_mode : gix_object :: tree :: EntryMode , # [doc = " The object id of the entry before the rename."] # [doc = ""] # [doc = " Note that this is the same as `id` if we require the [similarity to be 100%](gix_diff::Rewrites::percentage), but may"] # [doc = " be different otherwise."] source_id : Id < 'old > , # [doc = " Information about the diff we performed to detect similarity and match the `source_id` with the current state at `id`."] # [doc = " It's `None` if `source_id` is equal to `id`, as identity made an actual diff computation unnecessary."] diff : Option < gix_diff :: blob :: DiffLineStats > , # [doc = " The mode of the entry after the rename."] # [doc = " It could differ but still be considered a rename as we are concerned only about content."] entry_mode : gix_object :: tree :: EntryMode , # [doc = " The location of the destination file or directory, if [tracking](crate::diff::Options::track_path) was enabled."] # [doc = ""] # [doc = " It may be empty if neither [file names](crate::diff::Options::track_filename()) nor [file paths](crate::diff::Options::track_path())"] # [doc = " are tracked."] location : & 'a BStr , # [doc = " The object id after the rename."] id : Id < 'new > , # [doc = " Identifies a relationship between this destination and another destination,"] # [doc = " making it easy to reconstruct the top-level of directory changes."] relation : Option < tree :: visit :: Relation > , # [doc = " If true, this rewrite is created by copy, and `source_id` is pointing to its source. Otherwise, it's a rename, and `source_id`"] # [doc = " points to a deleted object, as renames are tracked as deletions and additions of the same or similar content."] copy : bool , } , }
    };
}

Change!()